CREATE OR REPLACE FUNCTION crm.cerrar_reunion(p_tarea_id uuid, p_estado text, p_resultado_reunion text DEFAULT NULL::text, p_motivo_no_realizada text DEFAULT NULL::text, p_detalle text DEFAULT NULL::text, p_siguiente jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := (select auth.uid());
  v_rol text := private.rol_crm((select auth.uid()));
  v_tarea crm.tareas%rowtype;
  v_act_id uuid;
  v_sig_id uuid;
  v_retroceso text;
begin
  if v_uid is null
     or v_rol not in ('vendedor', 'supervisor', 'gerencia') then
    raise exception 'No autorizado' using errcode = '42501';
  end if;
  if p_estado is null
     or p_estado not in ('completada', 'no_show', 'cancelada') then
    raise exception 'Estado de reunion invalido' using errcode = '22023';
  end if;
  if p_estado = 'completada'
     and (
       p_resultado_reunion is null
       or p_resultado_reunion not in (
         'interesado', 'seguimiento', 'propuesta',
         'inicia_registro', 'no_interesado'
       )
     ) then
    raise exception 'Registra el resultado comercial de la reunion'
      using errcode = '22023';
  end if;
  if p_estado = 'no_show' then
    p_motivo_no_realizada := 'cliente_no_asistio';
  elsif p_estado = 'cancelada'
        and (
          p_motivo_no_realizada is null
          or p_motivo_no_realizada not in (
            'cancelada_cliente', 'cancelada_empresa', 'otro'
          )
        ) then
    raise exception 'Registra el motivo de cancelacion'
      using errcode = '22023';
  end if;
  if p_estado = 'cancelada'
     and p_motivo_no_realizada = 'otro'
     and nullif(btrim(coalesce(p_detalle, '')), '') is null then
    raise exception 'Describe el otro motivo de cancelacion'
      using errcode = '22023';
  end if;

  perform 1
  from crm.leads
  where id = (
    select t.lead_id
    from crm.tareas t
    where t.id = p_tarea_id
      and t.tipo = 'reunion'
      and t.activo
      and t.estado = 'pendiente'
      and (
        v_rol = 'gerencia'
        or t.vendedor_id in (
          select private.vendedor_ids_visibles(v_uid)
        )
        or (
          t.vendedor_id is null
          and t.asignado_supervisor_id in (
            select private.vendedor_ids_visibles(v_uid)
          )
        )
      )
  )
  for no key update;

  select *
    into v_tarea
  from crm.tareas t
  where t.id = p_tarea_id
    and t.tipo = 'reunion'
    and t.activo
    and t.estado = 'pendiente'
    and (
      v_rol = 'gerencia'
      or t.vendedor_id in (
        select private.vendedor_ids_visibles(v_uid)
      )
      or (
        t.vendedor_id is null
        and t.asignado_supervisor_id in (
          select private.vendedor_ids_visibles(v_uid)
        )
      )
    )
  for update;
  if not found then
    raise exception 'Reunion no encontrada, cerrada o fuera de tu ambito';
  end if;

  if p_estado = 'completada' and v_tarea.lead_id is not null then
    insert into crm.actividades (
      lead_id, tipo, detalle, metadata, creado_por
    ) values (
      v_tarea.lead_id,
      'reunion_realizada',
      nullif(btrim(coalesce(p_detalle, '')), ''),
      jsonb_build_object(
        'modalidad', v_tarea.modalidad_reunion,
        'resultado_reunion', p_resultado_reunion,
        'tarea_id', v_tarea.id
      ),
      v_uid
    )
    returning id into v_act_id;
  elsif p_estado = 'no_show'
        and v_tarea.lead_id is not null
        and btrim(coalesce(p_detalle, '')) <> '' then
    insert into crm.actividades (
      lead_id, tipo, detalle, metadata, creado_por
    ) values (
      v_tarea.lead_id,
      'nota',
      btrim(p_detalle),
      jsonb_build_object(
        'evento', 'reunion_no_show',
        'tarea_id', v_tarea.id
      ),
      v_uid
    )
    returning id into v_act_id;
  end if;

  perform set_config('crm.op_tarea', 'on', true);
  update crm.tareas
     set estado = p_estado,
         resultado_actividad_id = v_act_id,
         resultado_reunion = case
           when p_estado = 'completada' then p_resultado_reunion
         end,
         motivo_no_realizada = case
           when p_estado in ('no_show', 'cancelada')
             then p_motivo_no_realizada
         end,
         detalle_cierre_reunion =
           nullif(btrim(coalesce(p_detalle, '')), '')
   where id = p_tarea_id;
  perform set_config('crm.op_tarea', 'off', true);

  v_sig_id := private.crear_siguiente_tarea(
    v_tarea,
    p_siguiente,
    case when p_estado = 'no_show' then p_tarea_id else null end,
    v_uid
  );

  if p_estado = 'cancelada' and v_tarea.lead_id is not null then
    v_retroceso := private.retroceso_por_anular_reunion(
      v_tarea.lead_id, p_tarea_id, v_uid
    );
  end if;

  return jsonb_build_object(
    'ok', true,
    'tarea_id', p_tarea_id,
    'actividad_id', v_act_id,
    'siguiente_id', v_sig_id,
    'retroceso', v_retroceso
  );
end;
$function$

CREATE OR REPLACE FUNCTION private.trg_gestion_lead_serializada()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := (select auth.uid());
  v_rol text;
  v_autorizado boolean := false;
begin
  -- Los writers internos (auth.uid NULL) y los eventos de sistema ya tienen
  -- sus propios gates. No deben quedar atrapados al dispararse desde un UPDATE
  -- del lead que ya posee el lock.
  if v_actor is null
     or (
       tg_table_name = 'actividades'
       and new.tipo in ('cambio_etapa', 'reasignacion', 'conversion')
     ) then
    return new;
  end if;

  -- `crm.tareas` también admite tareas de perfil sin lead; no participan en
  -- una devolución y conservan su policy existente.
  if new.lead_id is null then
    return new;
  end if;

  -- `creado_en` no es inmutable durante INSERT en las tablas heredadas. Un
  -- asesor podría enviar una fecha anterior a la asignación y hacer invisible
  -- su gestión para el candado de devolución. Los inserts manuales reciben un
  -- sello del servidor; writers internos con auth.uid NULL conservan backfill.
  -- Se preservan antes los contratos heredados de NOT NULL/fecha finita: el
  -- sello no debe convertir un payload imposible en una escritura válida.
  if new.creado_en is null then
    raise exception 'La fecha de creación de la gestión es obligatoria'
      using errcode = '23502';
  end if;
  if not pg_catalog.isfinite(new.creado_en) then
    raise exception 'La fecha de creación de la gestión debe ser finita'
      using errcode = '23514';
  end if;

  if new.creado_por is distinct from v_actor then
    raise exception 'La gestión debe quedar atribuida al usuario autenticado'
      using errcode = '42501';
  end if;

  v_rol := private.rol_crm(v_actor);
  select true
    into v_autorizado
  from crm.leads lead
  where lead.id = new.lead_id
    and lead.activo = true
    and (
      v_rol = 'gerencia'
      or lead.vendedor_id = v_actor
      or (
        v_rol = 'supervisor'
        and (
          lead.vendedor_id in (
            select private.vendedor_ids_visibles(v_actor)
          )
          or (
            lead.vendedor_id is null
            and lead.asignado_supervisor_id in (
              select private.vendedor_ids_visibles(v_actor)
            )
          )
        )
      )
    )
  for update;

  if v_autorizado is distinct from true then
    raise exception 'El lead cambió de responsable; recarga antes de registrar la gestión'
      using errcode = '42501';
  end if;
  -- F2.b (b2): el veto de la PERSONA bloquea el SEGUIMIENTO (contrato §7.3): los tipos
  -- de CONTACTO y las tareas. Las notas administrativas (corrección/anulación de un
  -- cierre, fusión, reingreso) no son contacto y siguen entrando; la nota de las RPC
  -- de veto entra además bajo la válvula op_privilegiada.
  if not coalesce(pg_catalog.current_setting('crm.op_privilegiada', true) = 'on', false)
     and (tg_table_name = 'tareas'
          or new.tipo in ('llamada_realizada','llamada_no_contestada','whatsapp_enviado','whatsapp_recibido','reunion_realizada'))
     and private.persona_vetada(new.lead_id) then
    raise exception '%: no se registra seguimiento', 'La persona tiene la restricción «No insistir»'
      using errcode = 'P0429';
  end if;

  -- El sello se toma DESPUÉS del lock y de la revalidación. `statement_timestamp`
  -- conservaría la hora previa a una espera: si una derivación ganara durante
  -- esa espera, la gestión podría quedar fechada antes del episodio y el
  -- supervisor aún la vería como reversible. `clock_timestamp` registra el
  -- orden causal ya serializado por el lock.
  new.creado_en := pg_catalog.clock_timestamp();

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.trg_leads_sla_versionado()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_en timestamptz;
  v_p crm.sla_politicas%rowtype;
  v_maximo integer;
  v_n integer;
  v_motivo text;
begin
  v_en:=case when tg_op='INSERT' then new.sla_global_iniciado_en else statement_timestamp() end;
  perform set_config('crm.sla_writer','on',true);

  if tg_op='INSERT' or new.ciclo_actual is distinct from old.ciclo_actual then
    select p.* into v_p from crm.sla_politicas p
    where p.id=private.sla_politica_vigente(new.sla_global_iniciado_en);
    if not found then raise exception 'No existe politica SLA para el ciclo'; end if;
    insert into crm.lead_sla_ciclos(
      lead_id,ciclo_n,politica_id,iniciado_en,primera_gestion_limite_en,primer_contacto_limite_en
    ) values(new.id,new.ciclo_actual,v_p.id,new.sla_global_iniciado_en,
      new.sla_global_iniciado_en+v_p.primera_gestion_minutos*interval '1 minute',
      new.sla_global_iniciado_en+v_p.primer_contacto_minutos*interval '1 minute');
  end if;

  if tg_op='UPDATE' and (
    new.ciclo_actual is distinct from old.ciclo_actual or new.etapa is distinct from old.etapa
    or (old.activo and not new.activo)
  ) then
    v_motivo:=case
      when new.ciclo_actual is distinct from old.ciclo_actual then 'reapertura'
      when old.activo and not new.activo then 'desactivacion'
      when new.etapa in ('convertido','descartado') then 'cierre_terminal'
      else 'cambio_etapa' end;
    update crm.lead_sla_etapas set finalizado_en=v_en,motivo_cierre=v_motivo
    where lead_id=new.id and finalizado_en is null;
  end if;

  if new.activo and new.etapa in ('nuevo','contactado','reunion_agendada','propuesta_enviada')
    and (tg_op='INSERT' or new.ciclo_actual is distinct from old.ciclo_actual
      or new.etapa is distinct from old.etapa or (not old.activo and new.activo)) then
    select p.* into v_p
    from crm.sla_politicas p
    where p.id=private.sla_politica_vigente(v_en);
    if not found then raise exception 'No existe politica SLA vigente'; end if;
    select pe.maximo_minutos into v_maximo
    from crm.sla_politica_etapas pe
    where pe.politica_id=v_p.id and pe.etapa=new.etapa;
    if not found then raise exception 'No existe SLA para etapa %',new.etapa; end if;
    select coalesce(max(e.episodio_n),0)+1 into v_n from crm.lead_sla_etapas e
    where e.lead_id=new.id and e.ciclo_n=new.ciclo_actual;
    insert into crm.lead_sla_etapas(
      lead_id,ciclo_n,episodio_n,etapa,politica_id,iniciado_en,limite_en
    ) values(new.id,new.ciclo_actual,v_n,new.etapa,v_p.id,v_en,
      v_en+v_maximo*interval '1 minute');
  end if;
  perform set_config('crm.sla_writer','off',true);
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.trg_tareas_before_insert()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_lead crm.leads%rowtype;
  v_cliente public.perfiles%rowtype;
  v_equipo crm.equipo%rowtype;
begin
  if new.lead_id is not null then
    -- El mismo row-lock serializa alta de tarea contra cierre/reasignación. Sin
    -- él, ambos commits podían dejar la tarea en el árbol anterior.
    select * into v_lead from crm.leads where id = new.lead_id for share;
    if not found then raise exception 'El lead de la tarea no existe'; end if;
    if v_lead.activo = false or v_lead.etapa in ('convertido','descartado') then
      raise exception 'El lead está cerrado: no admite tareas nuevas';
    end if;
    new.vendedor_id := v_lead.vendedor_id;
    new.asignado_supervisor_id := v_lead.asignado_supervisor_id;
  elsif new.perfil_id is not null then
    select * into v_cliente from public.perfiles p
    where p.id = new.perfil_id and p.rol = 'cliente'
    for share;
    if not found then raise exception 'El cliente de la tarea no existe'; end if;
    if not v_cliente.activo then
      raise exception 'El cliente está inactivo: no admite tareas comerciales nuevas';
    end if;
    if v_cliente.asesor_perfil_id is null then
      raise exception 'Asigna un Analista al cliente antes de agendar una gestión';
    end if;
    select * into v_equipo from crm.equipo e
    where e.perfil_id = v_cliente.asesor_perfil_id and e.activo
    for share;
    if not found or v_equipo.rol_crm not in ('vendedor','supervisor') then
      raise exception 'El Analista de la cartera no está activo en el CRM';
    end if;
    new.vendedor_id := v_cliente.asesor_perfil_id;
    new.asignado_supervisor_id := case
      when v_equipo.rol_crm = 'vendedor' then v_equipo.supervisor_id
      else null
    end;
  end if;

  if new.estado <> 'pendiente'
     and coalesce(current_setting('crm.op_tarea', true), 'off') <> 'on' then
    raise exception 'Una tarea nace pendiente; los cierres van por una RPC de agenda'
      using errcode = '22023';
  end if;
  if new.tipo = 'reunion' then
    new.modalidad_reunion := coalesce(new.modalidad_reunion, 'sin_clasificar');
  else
    new.modalidad_reunion := null;
    new.ubicacion_reunion := null;
    new.enlace_reunion := null;
    new.resultado_reunion := null;
    new.motivo_no_realizada := null;
    new.detalle_cierre_reunion := null;
  end if;
  if new.estado = 'pendiente' then
    new.resultado_reunion := null;
    new.motivo_no_realizada := null;
    new.detalle_cierre_reunion := null;
  end if;
  new.cancelada_por := case when new.estado = 'cancelada' then 'sistema' else null end;
  new.cancelada_por_id := null;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION crm.cerrar_tarea(p_tarea_id uuid, p_estado text, p_resultado_tipo text DEFAULT NULL::text, p_resultado_detalle text DEFAULT NULL::text, p_siguiente jsonb DEFAULT NULL::jsonb, p_resultado_reunion text DEFAULT NULL::text, p_motivo_no_realizada text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := (select auth.uid());
  v_rol text := private.rol_crm(v_uid);
  v_tarea crm.tareas%rowtype;
  v_act_id uuid;
  v_act_cliente_id uuid;
  v_sig_id uuid;
  v_retroceso text;
  v_detalle text := nullif(btrim(coalesce(p_resultado_detalle, '')), '');
begin
  if v_uid is null or v_rol not in ('vendedor','supervisor','gerencia') then
    raise exception 'No autorizado' using errcode = '42501';
  end if;
  if p_estado is null or p_estado not in ('completada','no_show','cancelada') then
    raise exception 'Estado de cierre inválido' using errcode = '22023';
  end if;

  select * into v_tarea
  from crm.tareas t
  where t.id = p_tarea_id and t.activo and t.estado = 'pendiente'
    and (
      v_rol = 'gerencia'
      or t.vendedor_id in (select private.vendedor_ids_visibles(v_uid))
      or (t.vendedor_id is null and t.asignado_supervisor_id in (
        select private.vendedor_ids_visibles(v_uid)
      ))
    )
  for update;
  if not found then
    raise exception 'Tarea no encontrada, cerrada o fuera de tu ámbito';
  end if;

  if v_tarea.lead_id is not null then
    perform 1 from crm.leads l where l.id = v_tarea.lead_id for no key update;
  else
    perform 1 from public.perfiles p where p.id = v_tarea.perfil_id for share;
  end if;

  if p_resultado_tipo is not null and p_resultado_tipo not in (
    'llamada_realizada','llamada_no_contestada','whatsapp_enviado',
    'whatsapp_recibido','reunion_realizada','nota'
  ) then
    raise exception 'Tipo de resultado inválido' using errcode = '22023';
  end if;
  if v_tarea.tipo = 'llamada' and p_estado = 'completada'
     and p_resultado_tipo is null then
    raise exception 'Registra el resultado de la llamada (contestó / no contestó)'
      using errcode = '22023';
  end if;

  -- Clasificación de reuniones: mismo contrato cerrado que cerrar_reunion. La
  -- validación ocurre ANTES del INSERT del timeline para que ningún rechazo
  -- deje una actividad huérfana, aun si la RPC se invoca fuera del frontend.
  if v_tarea.tipo <> 'reunion' then
    if p_resultado_reunion is not null or p_motivo_no_realizada is not null then
      raise exception 'Resultado y motivo de reunión solo aplican a reuniones'
        using errcode = '22023';
    end if;
  else
    if p_resultado_reunion is not null and p_resultado_reunion not in (
      'interesado','seguimiento','propuesta','inicia_registro','no_interesado'
    ) then
      raise exception 'Resultado comercial de reunión inválido' using errcode = '22023';
    end if;

    if p_estado = 'completada' then
      -- Compatibilidad de despliegue: el bundle anterior todavía llama los
      -- cinco parámetros. Solo ese payload ausente degrada a sin_clasificar;
      -- el frontend nuevo siempre envía el valor capturado.
      p_resultado_reunion := coalesce(p_resultado_reunion, 'sin_clasificar');
      p_motivo_no_realizada := null;
    elsif p_estado = 'no_show' then
      p_resultado_reunion := null;
      p_motivo_no_realizada := 'cliente_no_asistio';
    elsif p_estado = 'cancelada' then
      p_resultado_reunion := null;
      if p_motivo_no_realizada is null then
        -- Misma ventana de compatibilidad para el bundle anterior: evita que
        -- una publicación escalonada bloquee la agenda, sin inventar uno de
        -- los motivos comerciales específicos.
        p_motivo_no_realizada := 'otro';
        v_detalle := coalesce(
          v_detalle,
          'Compatibilidad: motivo no estructurado por cliente anterior'
        );
      elsif p_motivo_no_realizada not in ('cancelada_cliente','cancelada_empresa','otro') then
        raise exception 'Registra el motivo de cancelación' using errcode = '22023';
      end if;
      if p_motivo_no_realizada = 'otro' and v_detalle is null then
        raise exception 'Describe el otro motivo de cancelación' using errcode = '22023';
      end if;
    end if;
  end if;

  if p_resultado_tipo is not null and v_tarea.lead_id is not null then
    insert into crm.actividades (lead_id, tipo, detalle, creado_por)
    values (v_tarea.lead_id, p_resultado_tipo, v_detalle, v_uid)
    returning id into v_act_id;
  elsif p_resultado_tipo is not null and v_tarea.perfil_id is not null then
    insert into crm.actividades_cliente (
      cliente_id, vendedor_id, tarea_id, tipo, detalle, creado_por
    ) values (
      v_tarea.perfil_id, v_tarea.vendedor_id, v_tarea.id, p_resultado_tipo,
      v_detalle, v_uid
    ) returning id into v_act_cliente_id;
  end if;

  perform set_config('crm.op_tarea', 'on', true);
  update crm.tareas set
    estado = p_estado,
    resultado_actividad_id = v_act_id,
    resultado_reunion = case
      when v_tarea.tipo = 'reunion' and p_estado = 'completada'
        then p_resultado_reunion else null end,
    motivo_no_realizada = case
      when v_tarea.tipo = 'reunion' and p_estado in ('no_show','cancelada')
        then p_motivo_no_realizada else null end,
    detalle_cierre_reunion = case
      when v_tarea.tipo = 'reunion' then v_detalle else null end
  where id = p_tarea_id;
  perform set_config('crm.op_tarea', 'off', true);

  v_sig_id := private.crear_siguiente_tarea(
    v_tarea, p_siguiente,
    case when p_estado = 'no_show' then p_tarea_id else null end,
    v_uid
  );
  if p_estado = 'cancelada' and v_tarea.tipo = 'reunion'
     and v_tarea.lead_id is not null then
    v_retroceso := private.retroceso_por_anular_reunion(
      v_tarea.lead_id, p_tarea_id, v_uid
    );
  end if;

  return jsonb_build_object(
    'ok', true, 'tarea_id', p_tarea_id,
    'actividad_id', v_act_id,
    'actividad_cliente_id', v_act_cliente_id,
    'siguiente_id', v_sig_id, 'retroceso', v_retroceso
  );
end;
$function$

CREATE OR REPLACE FUNCTION crm.reprogramar_reunion(p_tarea_id uuid, p_vence_en timestamp with time zone, p_nueva_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := (select auth.uid());
  v_rol text := private.rol_crm((select auth.uid()));
  v_tarea crm.tareas%rowtype;
  v_nueva_id uuid := coalesce(p_nueva_id, gen_random_uuid());
begin
  if v_uid is null
     or v_rol not in ('vendedor', 'supervisor', 'gerencia') then
    raise exception 'No autorizado' using errcode = '42501';
  end if;
  if p_vence_en is null
     or p_vence_en < timestamptz '2026-01-01 00:00Z'
     or p_vence_en >= timestamptz '2100-01-01 00:00Z' then
    raise exception 'Fecha de reunion invalida' using errcode = '22023';
  end if;

  perform 1
  from crm.leads
  where id = (
    select t.lead_id
    from crm.tareas t
    where t.id = p_tarea_id
      and t.tipo = 'reunion'
      and t.activo
      and t.estado = 'pendiente'
      and (
        v_rol = 'gerencia'
        or t.vendedor_id in (
          select private.vendedor_ids_visibles(v_uid)
        )
        or (
          t.vendedor_id is null
          and t.asignado_supervisor_id in (
            select private.vendedor_ids_visibles(v_uid)
          )
        )
      )
  )
  for no key update;

  select *
    into v_tarea
  from crm.tareas t
  where t.id = p_tarea_id
    and t.tipo = 'reunion'
    and t.activo
    and t.estado = 'pendiente'
    and (
      v_rol = 'gerencia'
      or t.vendedor_id in (
        select private.vendedor_ids_visibles(v_uid)
      )
      or (
        t.vendedor_id is null
        and t.asignado_supervisor_id in (
          select private.vendedor_ids_visibles(v_uid)
        )
      )
    )
  for update;
  if not found then
    raise exception 'Reunion no encontrada, cerrada o fuera de tu ambito';
  end if;
  if p_vence_en = v_tarea.vence_en then
    raise exception 'La nueva fecha debe ser distinta'
      using errcode = '22023';
  end if;

  perform set_config('crm.op_tarea', 'on', true);
  update crm.tareas
     set estado = 'reprogramada',
         motivo_no_realizada = 'reprogramada',
         detalle_cierre_reunion = 'Reprogramada a ' || p_vence_en::text
   where id = p_tarea_id;
  perform set_config('crm.op_tarea', 'off', true);

  insert into crm.tareas (
    id, lead_id, perfil_id, tipo, titulo, nota, vence_en, duracion_min,
    modalidad_reunion, ubicacion_reunion, enlace_reunion,
    reagendada_de, reprogramaciones, creado_por
  ) values (
    v_nueva_id,
    v_tarea.lead_id,
    v_tarea.perfil_id,
    'reunion',
    v_tarea.titulo,
    v_tarea.nota,
    p_vence_en,
    v_tarea.duracion_min,
    v_tarea.modalidad_reunion,
    v_tarea.ubicacion_reunion,
    v_tarea.enlace_reunion,
    v_tarea.id,
    v_tarea.reprogramaciones + 1,
    v_uid
  );

  return jsonb_build_object(
    'ok', true,
    'tarea_anterior_id', p_tarea_id,
    'tarea_nueva_id', v_nueva_id,
    'reprogramaciones', v_tarea.reprogramaciones + 1
  );
end;
$function$

CREATE OR REPLACE FUNCTION private.trg_tareas_before_update()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_op      boolean := coalesce(current_setting('crm.op_tarea', true), 'off') = 'on';
  v_sistema boolean := coalesce(current_setting('crm.cancela_sistema', true), 'off') = 'on';
  v_uid     uuid    := (select auth.uid());
  v_asesor  boolean;
  v_cambio_vencimiento boolean;
begin
  v_cambio_vencimiento := new.vence_en is distinct from old.vence_en;

  if old.estado <> 'pendiente' then
    raise exception 'La tarea ya esta cerrada; una reunion reprogramada conserva su historia'
      using errcode = '22023';
  end if;
  if new.estado in ('completada','no_show','reprogramada') and not v_op then
    raise exception 'Cerrar o reprogramar una reunion va por la RPC de agenda'
      using errcode = '22023';
  end if;
  if new.estado = 'cancelada' and not v_op and not v_sistema and v_uid is not null then
    raise exception 'Anular una tarea va por crm.cerrar_tarea()'
      using errcode = '22023';
  end if;
  if new.resultado_actividad_id is distinct from old.resultado_actividad_id and not v_op then
    raise exception 'El resultado lo escribe la RPC de cierre'
      using errcode = '22023';
  end if;
  if (
    new.resultado_reunion is distinct from old.resultado_reunion
    or new.motivo_no_realizada is distinct from old.motivo_no_realizada
    or new.detalle_cierre_reunion is distinct from old.detalle_cierre_reunion
  ) and not v_op then
    raise exception 'El resultado de la reunion lo escribe la RPC de cierre'
      using errcode = '22023';
  end if;
  if old.tipo = 'reunion' and v_cambio_vencimiento and not v_op then
    raise exception 'Reprogramar una reunion va por crm.reprogramar_reunion()'
      using errcode = '22023';
  end if;

  if new.estado = 'cancelada' then
    v_asesor := (not v_sistema) and v_op and v_uid is not null;
    new.cancelada_por    := case when v_asesor then 'asesor' else 'sistema' end;
    new.cancelada_por_id := case when v_asesor then v_uid else null end;
  else
    new.cancelada_por    := old.cancelada_por;
    new.cancelada_por_id := old.cancelada_por_id;
  end if;

  new.creado_por := old.creado_por;
  new.creado_en := old.creado_en;
  new.lead_id := old.lead_id;
  new.perfil_id := old.perfil_id;
  new.reagendada_de := old.reagendada_de;
  new.tipo := old.tipo;
  new.modalidad_reunion := old.modalidad_reunion;
  new.ubicacion_reunion := old.ubicacion_reunion;
  new.enlace_reunion := old.enlace_reunion;

  if v_cambio_vencimiento then
    new.reprogramaciones := old.reprogramaciones + 1;
  else
    new.reprogramaciones := old.reprogramaciones;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.trg_leads_asignaciones()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_evento_en timestamptz;
  v_actor uuid;
  v_movimiento text := 'sin_cambio';
  v_abierto crm.lead_asignaciones%rowtype;
  v_hay_abierto boolean := false;
  v_old_debe_tener boolean := false;
  v_new_debe_tener boolean;
  v_entra_terminal boolean := false;
  v_reabierto boolean := false;
  v_reactivado boolean := false;
  v_motivo_apertura text;
  v_motivo_cierre text;
  v_episodio_n integer;
  v_abiertos integer;
  v_analista_abierto uuid;
begin
  v_new_debe_tener := new.activo = true
    and new.etapa in ('nuevo', 'contactado', 'reunion_agendada', 'propuesta_enviada')
    and new.vendedor_id is not null;

  if tg_op = 'INSERT' then
    v_evento_en := new.creado_en;
    v_actor := coalesce(auth.uid(), new.creado_por);

    if v_new_debe_tener then
      perform set_config('crm.ledger_writer', 'on', true);
      insert into crm.lead_asignaciones (
        lead_id,
        ciclo_n,
        episodio_n,
        analista_id,
        motivo_apertura,
        asignado_en,
        asignado_por,
        monto_estimado,
        moneda,
        origen,
        categoria_interes
      )
      values (
        new.id,
        new.ciclo_actual,
        1,
        new.vendedor_id,
        'ingreso',
        v_evento_en,
        v_actor,
        new.monto_estimado,
        new.moneda,
        new.origen,
        new.categoria_interes
      );
      perform set_config('crm.ledger_writer', 'off', true);
    end if;
  else
    v_evento_en := statement_timestamp();
    v_actor := auth.uid();
    v_movimiento := private.clasificar_movimiento_tenencia(
      old.vendedor_id,
      new.vendedor_id,
      old.asignado_supervisor_id,
      new.asignado_supervisor_id
    );
    v_old_debe_tener := old.activo = true
      and old.etapa in ('nuevo', 'contactado', 'reunion_agendada', 'propuesta_enviada')
      and old.vendedor_id is not null;
    v_entra_terminal := old.etapa not in ('convertido', 'descartado')
      and new.etapa in ('convertido', 'descartado');
    v_reabierto := old.etapa = 'descartado' and new.etapa = 'nuevo';
    v_reactivado := old.activo = false and new.activo = true;

    select la.*
      into v_abierto
    from crm.lead_asignaciones la
    where la.lead_id = new.id
      and la.finalizado_en is null
    for update;
    v_hay_abierto := found;

    if v_old_debe_tener and not v_hay_abierto then
      raise exception 'Invariante rota: falta el episodio abierto del lead %', new.id;
    end if;
    if v_old_debe_tener and v_abierto.analista_id is distinct from old.vendedor_id then
      raise exception 'Invariante rota: el episodio abierto no coincide con el analista del lead %', new.id;
    end if;
    if not v_old_debe_tener and v_hay_abierto then
      raise exception 'Invariante rota: existe un episodio abierto fuera de tenencia operativa para %', new.id;
    end if;

    if v_hay_abierto
       and (
         new.vendedor_id is distinct from old.vendedor_id
         or not v_new_debe_tener
       ) then
      v_motivo_cierre := case
        when v_entra_terminal then new.etapa
        when old.activo = true and new.activo = false then 'desactivado'
        when v_movimiento = 'transferido' then 'transferido'
        when v_movimiento in ('parqueado', 'sin_asignar') then 'parqueado'
        else null
      end;

      if v_motivo_cierre is null then
        raise exception 'No se pudo clasificar el cierre del episodio del lead %', new.id;
      end if;

      perform set_config('crm.ledger_writer', 'on', true);
      update crm.lead_asignaciones
      set finalizado_en = v_evento_en,
          finalizado_por = v_actor,
          motivo_cierre = v_motivo_cierre,
          analista_destino_id = case
            when v_motivo_cierre = 'transferido' then new.vendedor_id
            else null
          end,
          supervisor_destino_id = case
            when v_motivo_cierre = 'parqueado' then new.asignado_supervisor_id
            else null
          end,
          resultado = case
            when v_motivo_cierre in ('convertido', 'descartado') then v_motivo_cierre
            else null
          end,
          resultado_en = case
            when v_motivo_cierre in ('convertido', 'descartado') then v_evento_en
            else null
          end,
          motivo_descarte_cierre = case
            when v_motivo_cierre = 'descartado' then new.motivo_descarte
            else null
          end
      where id = v_abierto.id;
      perform set_config('crm.ledger_writer', 'off', true);
      v_hay_abierto := false;
    end if;

    if v_new_debe_tener
       and (
         not v_old_debe_tener
         or new.vendedor_id is distinct from old.vendedor_id
       ) then
      v_motivo_apertura := case
        when v_reabierto then 'reabierto'
        when v_reactivado then 'reactivado'
        when v_movimiento = 'transferido' then 'reasignado'
        else 'asignado'
      end;

      select coalesce(max(la.episodio_n), 0) + 1
        into v_episodio_n
      from crm.lead_asignaciones la
      where la.lead_id = new.id
        and la.ciclo_n = new.ciclo_actual;

      perform set_config('crm.ledger_writer', 'on', true);
      insert into crm.lead_asignaciones (
        lead_id,
        ciclo_n,
        episodio_n,
        analista_id,
        motivo_apertura,
        asignado_en,
        asignado_por,
        supervisor_origen_id,
        monto_estimado,
        moneda,
        origen,
        categoria_interes
      )
      values (
        new.id,
        new.ciclo_actual,
        v_episodio_n,
        new.vendedor_id,
        v_motivo_apertura,
        v_evento_en,
        v_actor,
        old.asignado_supervisor_id,
        new.monto_estimado,
        new.moneda,
        new.origen,
        new.categoria_interes
      );
      perform set_config('crm.ledger_writer', 'off', true);
    end if;
  end if;

  select count(*), (array_agg(la.analista_id))[1]
    into v_abiertos, v_analista_abierto
  from crm.lead_asignaciones la
  where la.lead_id = new.id
    and la.finalizado_en is null;

  if v_new_debe_tener
     and (v_abiertos <> 1 or v_analista_abierto is distinct from new.vendedor_id) then
    raise exception 'Invariante rota: el lead % debe terminar con un episodio abierto', new.id;
  end if;
  if not v_new_debe_tener and v_abiertos <> 0 then
    raise exception 'Invariante rota: el lead % no debe terminar con episodio abierto', new.id;
  end if;

  return new;
end;
$function$
